package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var TaxRecData TaxRec
var inputFile *os.File
var scanner *bufio.Scanner

var d10000 = decimal.NewFromInt(10000)
var d40000 = decimal.NewFromInt(40000)
var d1000 = decimal.NewFromInt(1000)
var d7000 = decimal.NewFromInt(7000)
var d010 = decimal.RequireFromString("0.10")
var d020 = decimal.RequireFromString("0.20")
var d030 = decimal.RequireFromString("0.30")

func parsePIC9V99(s string, scale int) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(t)
	if err != nil {
		filtered := ""
		for _, r := range t {
			if (r >= '0' && r <= '9') || r == '-' || r == '+' {
				filtered += string(r)
			}
		}
		if filtered == "" {
			return decimal.NewFromInt(0)
		}
		d, err = decimal.NewFromString(filtered)
		if err != nil {
			return decimal.NewFromInt(0)
		}
	}
	return d.Shift(int32(-scale))
}

func countDigits(pic string) int {
	c := 0
	for _, ch := range pic {
		if ch == 'Z' || ch == '9' {
			c++
		}
	}
	return c
}

func applyOverflow(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if intDigits <= 0 {
		return v
	}
	sign := v.Sign()
	abs := v.Abs()
	sFixed := abs.StringFixed(int32(scale))
	parts := strings.Split(sFixed, ".")
	intPart := parts[0]
	fracPart := ""
	if scale > 0 {
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", scale)
		}
		if len(fracPart) < scale {
			fracPart += strings.Repeat("0", scale-len(fracPart))
		}
		if len(fracPart) > scale {
			fracPart = fracPart[:scale]
		}
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	var combined string
	if scale > 0 {
		combined = intPart + "." + fracPart
	} else {
		combined = intPart
	}
	d, _ := decimal.NewFromString(combined)
	if sign < 0 {
		d = d.Neg()
	}
	return d
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int, rounded bool) decimal.Decimal {
	var v2 decimal.Decimal
	if rounded {
		v2 = v.Round(int32(scale))
	} else {
		v2 = v.Truncate(int32(scale))
	}
	return applyOverflow(v2, intDigits, scale)
}

func storeInt(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if v >= 0 {
		return v % mod
	}
	abs := -v
	return -(abs % mod)
}

func formatCount(c int64) string {
	return fmt.Sprintf("%03d", c)
}

func formatNumericEdited(value decimal.Decimal, picture string) string {
	isNeg := value.Sign() < 0
	abs := value.Abs()

	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intPlaceCount := countDigits(intPic)
	fracPlaceCount := countDigits(fracPic)

	var rounded decimal.Decimal
	if fracPlaceCount > 0 {
		rounded = abs.Round(int32(fracPlaceCount))
	} else {
		rounded = abs.Round(0)
	}

	var sFixed string
	if fracPlaceCount > 0 {
		sFixed = rounded.StringFixed(int32(fracPlaceCount))
	} else {
		sFixed = rounded.StringFixed(0)
	}
	parts := strings.Split(sFixed, ".")
	intPartStr := parts[0]
	fracPartStr := ""
	if fracPlaceCount > 0 {
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", fracPlaceCount)
		}
		if len(fracPartStr) < fracPlaceCount {
			fracPartStr += strings.Repeat("0", fracPlaceCount-len(fracPartStr))
		}
		if len(fracPartStr) > fracPlaceCount {
			fracPartStr = fracPartStr[:fracPlaceCount]
		}
	}
	if len(intPartStr) > intPlaceCount {
		intPartStr = intPartStr[len(intPartStr)-intPlaceCount:]
	}
	if len(intPartStr) < intPlaceCount {
		intPartStr = strings.Repeat("0", intPlaceCount-len(intPartStr)) + intPartStr
	}

	integerOutput := make([]rune, len(intPic))
	suppressed := true
	digitIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			digitChar := rune(intPartStr[digitIdx])
			digitIdx++
			if ch == 'Z' {
				if suppressed && digitChar == '0' {
					integerOutput[i] = ' '
				} else {
					integerOutput[i] = digitChar
					suppressed = false
				}
			} else {
				integerOutput[i] = digitChar
				suppressed = false
			}
		} else if ch == ',' {
			if suppressed {
				integerOutput[i] = ' '
			} else {
				integerOutput[i] = ','
			}
		} else {
			integerOutput[i] = ch
		}
	}

	var result string
	if dotPos >= 0 {
		result = string(integerOutput) + "." + fracPartStr
	} else {
		result = string(integerOutput)
	}

	if isNeg {
		runes := []rune(result)
		firstDigitIdx := -1
		for i, r := range runes {
			if r >= '0' && r <= '9' {
				firstDigitIdx = i
				break
			}
		}
		if firstDigitIdx != -1 {
			signPos := -1
			for i := firstDigitIdx - 1; i >= 0; i-- {
				if runes[i] == ' ' {
					signPos = i
					break
				}
			}
			if signPos != -1 {
				runes[signPos] = '-'
			} else {
				if len(runes) > 0 {
					runes[0] = '-'
				}
			}
			result = string(runes)
		}
	}
	return result
}

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		TaxRecData.TrId = line[0:5]
		incomeStr := line[5:13]
		TaxRecData.TrIncome = parsePIC9V99(incomeStr, 2)
		WsEofFlag = "N"
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if TaxRecData.TrIncome.Cmp(d10000) <= 0 {
		raw := TaxRecData.TrIncome.Mul(d010)
		WsTax = storeDecimal(raw, 7, 2, true)
	} else if TaxRecData.TrIncome.Cmp(d40000) <= 0 {
		diff := TaxRecData.TrIncome.Sub(d10000)
		raw := d1000.Add(diff.Mul(d020))
		WsTax = storeDecimal(raw, 7, 2, true)
	} else {
		diff := TaxRecData.TrIncome.Sub(d40000)
		raw := d7000.Add(diff.Mul(d030))
		WsTax = storeDecimal(raw, 7, 2, true)
	}
	rawNet := TaxRecData.TrIncome.Sub(WsTax)
	WsNet = storeDecimal(rawNet, 7, 2, false)
	WsTotalTax = storeDecimal(WsTotalTax.Add(WsTax), 9, 2, false)
	WsCount = storeInt(WsCount+1, 3)
	WsIncEd = formatNumericEdited(TaxRecData.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatNumericEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatNumericEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", TaxRecData.TrId, WsIncEd, WsTaxEd, WsNetEd)
	ReadPara()
}

func MainPara() {
	var err error
	inputFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer inputFile.Close()
	scanner = bufio.NewScanner(inputFile)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	WsTotalEd = formatNumericEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", formatCount(WsCount), WsTotalEd)
}

func main() {
	MainPara()
}
